CREATE OR REPLACE FUNCTION public.dispatch_job_refresh(p_url text, p_secret text, p_force boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; queued jsonb='[]'::jsonb; req bigint; BEGIN IF p_url !~ '^https?://[^/]+/api/public/cron/jobs-sync$' OR length(p_secret)<16 THEN RAISE EXCEPTION 'Invalid refresh configuration'; END IF; FOR s IN SELECT slug FROM public.job_sources WHERE active AND status='connected' AND (locked_until IS NULL OR locked_until<now()) AND (retry_after IS NULL OR retry_after<=now()) AND (p_force OR last_synced_at IS NULL OR last_synced_at+make_interval(mins=>poll_minutes)<=now()) ORDER BY id LOOP SELECT net.http_post(url:=p_url,headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||p_secret),body:=jsonb_build_object('mode','source','sourceSlug',s.slug,'force',p_force),timeout_milliseconds:=300000) INTO req; queued=queued||jsonb_build_array(jsonb_build_object('source',s.slug,'status','queued')); END LOOP; PERFORM net.http_post(url:=p_url,headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||p_secret),body:='{"mode":"maintenance"}'::jsonb,timeout_milliseconds:=300000); RETURN queued; END $$;
REVOKE ALL ON FUNCTION public.dispatch_job_refresh(text,text,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dispatch_job_refresh(text,text,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.recover_job_source_runs(p_source uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.source_sync_runs SET finished_at=now(),status='failed',error='Interrupted refresh lease expired' WHERE source_id=p_source AND finished_at IS NULL AND started_at<now()-interval '5 minutes' AND NOT EXISTS(SELECT 1 FROM public.job_sources WHERE id=p_source AND locked_until>now()); END $$;
REVOKE ALL ON FUNCTION public.recover_job_source_runs(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.recover_job_source_runs(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.dedupe_job_refresh() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN WITH live AS (SELECT j.id,j.dedupe_key,j.canonical_apply_url,j.original_posted_at,s.provider FROM public.jobs j JOIN public.job_sources s ON s.id=j.source_id WHERE j.original_posted_at>now()-interval '7 days' AND j.application_status='OPEN' AND j.verification_status='VERIFIED' AND j.source_access_status='AUTHORIZED' AND NOT j.admin_hold AND j.expires_at>now()), ranked AS (SELECT id,row_number() OVER(PARTITION BY dedupe_key ORDER BY (provider='remoteok'),original_posted_at,id) title_rank, CASE WHEN canonical_apply_url IS NULL THEN 1 ELSE row_number() OVER(PARTITION BY canonical_apply_url ORDER BY (provider='remoteok'),original_posted_at,id) END url_rank FROM live) UPDATE public.jobs j SET is_primary=(r.title_rank=1 AND r.url_rank=1) FROM ranked r WHERE j.id=r.id AND j.is_primary IS DISTINCT FROM (r.title_rank=1 AND r.url_rank=1); END $$;
REVOKE ALL ON FUNCTION public.dedupe_job_refresh() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dedupe_job_refresh() TO service_role;